const item = $input.first().json;
const station = item.station || item; // tolerate {station:{...}} or flat

const providerCode = $env.PROVIDER_CODE || 'hkev';
const externalId = String(station.id ?? station.station_id ?? station.external_id);
if (!externalId) {
  throw new Error(providerCode + ' station missing id/station_id/external_id: ' + JSON.stringify(station).slice(0, 200));
}

// ---------- QR HMAC (SHA-256, vendored for n8n's sandboxed JS env) ----------
const secret = $env.QR_HMAC_SECRET || '';
function hmacHex8(secretStr, message) {
  function sha256(ascii) {
    function rightRotate(value, amount) { return (value >>> amount) | (value << (32 - amount)); }
    const maxWord = Math.pow(2, 32);
    let result = '';
    const words = [];
    const asciiBitLength = ascii.length * 8;
    const hash = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
    const k = [
      0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
      0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
      0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
      0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
      0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
      0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
      0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
      0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
    ];
    let hashTemp = hash.slice(0);
    ascii += '\x80';
    while ((ascii.length % 64) - 56) ascii += '\x00';
    for (let i = 0; i < ascii.length; i++) {
      const j = ascii.charCodeAt(i);
      if (j >> 8) return undefined;
      words[i >> 2] |= j << (((3 - i) % 4) * 8);
    }
    words[words.length] = ((asciiBitLength / maxWord) | 0);
    words[words.length] = (asciiBitLength);
    for (let j = 0; j < words.length;) {
      const w = words.slice(j, j += 16);
      const oldHash = hashTemp.slice(0);
      for (let i = 0; i < 64; i++) {
        const w15 = w[i - 15], w2 = w[i - 2];
        const a = hashTemp[0], e = hashTemp[4];
        const temp1 = hashTemp[7]
          + (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25))
          + ((e & hashTemp[5]) ^ (~e & hashTemp[6]))
          + k[i]
          + (w[i] = (i < 16) ? w[i] :
            (w[i - 16] + (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3))
             + w[i - 7]
             + (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))) | 0);
        const temp2 = (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22))
          + ((a & hashTemp[1]) ^ (a & hashTemp[2]) ^ (hashTemp[1] & hashTemp[2]));
        hashTemp = [(temp1 + temp2) | 0].concat(hashTemp).slice(0, 8);
        hashTemp[4] = (hashTemp[4] + temp1) | 0;
      }
      for (let i = 0; i < 8; i++) hash[i] = (hash[i] + hashTemp[i]) | 0;
    }
    for (let i = 0; i < 8; i++) {
      for (let j = 3; j + 1; j--) {
        const b = (hash[i] >> (j * 8)) & 255;
        result += ((b < 16) ? '0' : '') + b.toString(16);
      }
    }
    return result;
  }
  function hmacSha256(key, message) {
    let k = key;
    if (k.length > 64) k = sha256(k);
    while (k.length < 64) k += '\x00';
    const oKeyPad = k.split('').map(c => String.fromCharCode(c.charCodeAt(0) ^ 0x5c)).join('');
    const iKeyPad = k.split('').map(c => String.fromCharCode(c.charCodeAt(0) ^ 0x36)).join('');
    return sha256(oKeyPad + sha256(iKeyPad + message));
  }
  const mac = hmacSha256(secretStr, message);
  return mac.slice(0, 16);
}

const poles = Array.isArray(station.poles) ? station.poles : [];
const canonicalPoles = poles.map(p => {
  const poleExternalId = String(p.id ?? p.pole_id ?? p.external_id);
  const qrPayload = providerCode + '://' + poleExternalId + '-' + externalId + '-' + hmacHex8(secret, poleExternalId + ':' + externalId);

  const connector = String(p.connector || p.connector_type || 'ccs2').toLowerCase();
  const allowedConnectors = ['ccs2','type2','chademo','tesla'];
  const safeConnector = allowedConnectors.includes(connector) ? connector : 'ccs2';

  const speedTier = String(p.speed_tier || p.tier || 'ac_slow').toLowerCase();
  const allowedTiers = ['ac_slow','ac_fast','dc_fast','dc_ultra'];
  const safeTier = allowedTiers.includes(speedTier) ? speedTier : 'ac_slow';

  return {
    external_id: poleExternalId,
    connector: safeConnector,
    speed_tier: safeTier,
    max_kw: String(p.max_kw ?? p.kw ?? 0),
    qr_code: qrPayload,
    status: 'unknown',
    status_updated_at: new Date().toISOString(),
    hourly_rates: Array.isArray(p.hourly_rates) ? p.hourly_rates.map(r => ({
      day_of_week: Number.isInteger(r.day_of_week) ? r.day_of_week : 0,
      hour_start_local: r.hour_start_local || r.hour || '00:00:00',
      price_per_kwh_hkd: String(r.price_per_kwh_hkd ?? r.price ?? 0),
      parking_fee_hkd: String(r.parking_fee_hkd ?? 0),
      valid_from: r.valid_from || new Date().toISOString(),
      valid_to: r.valid_to || null
    })) : []
  };
});

const payload = {
  station: {
    external_id: externalId,
    provider_code: providerCode,
    name: String(station.name || station.title || (providerCode.toUpperCase() + ' Station ' + externalId)),
    address: String(station.address || station.addr || ''),
    district: station.district || station.area || null,
    latitude: String(station.latitude ?? station.lat ?? 0),
    longitude: String(station.longitude ?? station.lng ?? station.lon ?? 0),
    parking_fee_hkd: String(station.parking_fee_hkd ?? 0),
    amenities: Array.isArray(station.amenities) ? station.amenities : [],
    raw_payload: station
  },
  poles: canonicalPoles,
  replace_rates: true
};

return { json: payload };
